function tttWinner(b){
  var L=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
  for(var i=0;i<L.length;i++){ var a=L[i][0],c=L[i][1],d=L[i][2]; if(b[a]&&b[a]===b[c]&&b[a]===b[d]) return b[a]; }
  var full=true; for(var k=0;k<9;k++) if(!b[k]) full=false;
  return full?'draw':null;
}
function tttMove(b, player){
  var opp=player==='X'?'O':'X'; var w=tttWinner(b);
  if(w) return {move:-1, score: w===player?1 : w==='draw'?0 : -1};
  var best=-2, bestMove=-1;
  for(var i=0;i<9;i++){ if(!b[i]){ b[i]=player; var r=-tttMove(b, opp).score; b[i]=null; if(r>best){ best=r; bestMove=i; } } }
  return {move:bestMove, score:best};
}

var EXPORTS={tttWinner:tttWinner,tttMove:tttMove};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TicTacForgePure = EXPORTS; }
